CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, jlpt_level text NOT NULL DEFAULT 'N5', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL DEFAULT 'New conversation', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('user','assistant','system')), parts jsonb NOT NULL, prompt_version text, model text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS messages_conversation_idx ON messages(conversation_id,created_at);
CREATE TABLE IF NOT EXISTS source_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_title text NOT NULL, section text NOT NULL, provenance text NOT NULL, content text NOT NULL, embedding vector(1024), metadata jsonb);
CREATE INDEX IF NOT EXISTS source_chunks_embedding_idx ON source_chunks USING hnsw (embedding vector_cosine_ops);
CREATE TABLE IF NOT EXISTS lesson_cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, kanji text NOT NULL, kana text NOT NULL, meaning text NOT NULL, example text, part_of_speech text, pitch text, due_at timestamptz NOT NULL, stability real NOT NULL DEFAULT 0, difficulty real NOT NULL DEFAULT 5, reps integer NOT NULL DEFAULT 0, lapses integer NOT NULL DEFAULT 0, last_review_at timestamptz, scheduled_days real NOT NULL DEFAULT 0, fsrs_state text NOT NULL DEFAULT 'New', scheduler_version text NOT NULL DEFAULT 'fsrs-5', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS review_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), card_id uuid NOT NULL REFERENCES lesson_cards(id) ON DELETE CASCADE, rating integer NOT NULL CHECK (rating BETWEEN 1 AND 4), reviewed_at timestamptz NOT NULL, due_at_after timestamptz NOT NULL, stability_after real NOT NULL, difficulty_after real NOT NULL, scheduler_version text NOT NULL);
CREATE INDEX IF NOT EXISTS reviews_card_time_idx ON review_events(card_id,reviewed_at);
CREATE TABLE IF NOT EXISTS quiz_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, source_conversation_id uuid REFERENCES conversations(id) ON DELETE SET NULL, questions jsonb NOT NULL, score real, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_user (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_session (id text PRIMARY KEY, expires_at timestamptz NOT NULL, token text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS auth_account (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
